function getRecordedFutureTranslation(key, lang) {
    return (recordedfutureTranslations[lang] && recordedfutureTranslations[lang][key]) ||
           (recordedfutureTranslations.en && recordedfutureTranslations.en[key]) || null;
}

function applyRecordedFutureTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.recorded-future.") || key.startsWith("review.common."))) {
            const translation = getRecordedFutureTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} recorded-future translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyRecordedFutureTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyRecordedFutureTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyRecordedFutureTranslations(window.i18n?.getCurrentLanguage() || "en");
}
